// Package highlight splits the text of a previewed file into coloured runs.
//
// Chroma owns the languages: its lexers decide what a token is, so nothing here
// lists a syntax. A token carries chroma's own class name rather than a colour,
// and the stylesheet behind those classes is generated by ./generate from the
// shared palette, so a preview is coloured like the rest of the window whatever
// theme it is in.
package highlight

import (
	"github.com/alecthomas/chroma/v2"
	"github.com/alecthomas/chroma/v2/lexers"
)

//go:generate go run ./generate -out ../../frontend/src/highlight.css

// ClassPrefix guards chroma's class names, which are single letters, against
// everything else the frontend's stylesheet holds. The generator needs it too,
// so the tokens and the sheet cannot drift apart.
const ClassPrefix = "hl-"

// Token is one run of text drawn in one colour. Class is the CSS class the
// stylesheet gives that colour to, empty for text that takes the pane's own.
type Token struct {
	Class string `json:"class"`
	Text  string `json:"text"`
}

// Tokens splits source into coloured runs, taking the language from the file
// name. It returns nothing for a file type no lexer covers, which leaves the
// caller with the plain text it already had.
func Tokens(fileName string, source string) []Token {
	lexer := lexers.Match(fileName)
	if lexer == nil {
		return nil
	}
	iterator, err := chroma.Coalesce(lexer).Tokenise(nil, source)
	if err != nil {
		return nil
	}
	return collect(iterator)
}

func collect(iterator chroma.Iterator) []Token {
	tokens := []Token{}
	for token := iterator(); token != chroma.EOF; token = iterator() {
		if token.Value == "" {
			continue
		}
		tokens = append(tokens, Token{Class: classOf(token.Type), Text: token.Value})
	}
	if len(tokens) == 0 {
		return nil
	}
	return tokens
}

// Chroma names most token types but not all of them: an unnamed one takes the
// name of the closest parent that has one, which is the colour it inherits in
// the stylesheet as well.
func classOf(tokenType chroma.TokenType) string {
	for tokenType != 0 {
		name, named := chroma.StandardTypes[tokenType]
		if named {
			return prefixed(name)
		}
		tokenType = tokenType.Parent()
	}
	return prefixed(chroma.StandardTypes[tokenType])
}

func prefixed(name string) string {
	if name == "" {
		return ""
	}
	return ClassPrefix + name
}
